}
function on$GridReport$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender;
	switch (action) {
		case 'Print':
			e.type.cancelEvent = !isCheck$Grid(g);
			break;
		case 'PrintMultiForm':
			// THÊM: nút "In nhiều mẫu" - cho tick nhiều mẫu in, in cùng lúc cho
			// TẤT CẢ chứng từ đã tick (lệnh Print gốc của màn hình này tự in
			// theo các dòng đã tick, nên mỗi mẫu gọi lại là in cả loạt).
			// Toàn bộ xử lý nằm trong file dùng chung
			// ~/ClientScript/viewer-libs/print-multi-form.js (cùng file với màn
			// hình SVTran), nạp lazy qua ensure$PrintMultiForm$Script bên dưới.
			e.type.cancelEvent = true;
			if (typeof isCheck$Grid === 'function' && !isCheck$Grid(g)) break;
			ensure$PrintMultiForm$Script(g, function () { open$PrintMultiForm$Dialog(g); });
			break;
		default:
			break;
	}
}
// Đổi số version này mỗi khi sửa nội dung print-multi-form.js để trình
// duyệt tự tải lại bản mới (không bị cache cũ giữ lại). Nhớ đổi ĐỒNG BỘ
// với biến cùng tên trong Grid\SVTran.xml (2 màn hình dùng chung 1 file js).
var PRINT_MULTI_FORM_SCRIPT_VERSION = '4';
function ensure$PrintMultiForm$Script(g, callback) {
	if (typeof open$PrintMultiForm$Dialog !== 'undefined') { callback(); return; }
	var s = document.createElement('script');
	s.src = $func.resolveClientUrl('~/ClientScript/viewer-libs/print-multi-form.js', g._baseUrl) + '?v=' + PRINT_MULTI_FORM_SCRIPT_VERSION;
	s.onload = callback;
	s.onerror = function () {
		window.alert(g._language == 'v' ? 'Không tải được file xử lý in nhiều mẫu (~\\ClientScript\\viewer-libs\\print-multi-form.js). Kiểm tra lại đã upload file lên đúng chỗ chưa.' : 'Could not load print-multi-form.js. Check the file was uploaded to the right path.');
	};
	document.getElementsByTagName('head')[0].appendChild(s);
}
